NAME = 'KLV: Klingon Language Version of the World English Bible'
BOOK = 'Zechariah'

CHAPTERS = {
    1: {
        1: "Daq the eighth jar, Daq the cha'DIch DIS vo' Darius, the mu' vo' joH'a' ghoSta' Daq Zechariah the puqloD vo' Berechiah, the puqloD vo' Iddo, the leghwI'pu', ja'ta',",
        2: "“joH'a' ghaHta' very displeased tlhej lIj vavpu'.",
        3: "vaj ja' chaH: Thus jatlhtaH joH'a' vo' Armies: ‘chegh Daq jIH,' jatlhtaH joH'a' vo' Armies, ‘je jIH DichDaq chegh Daq SoH,' jatlhtaH joH'a' vo' Armies.",
        4: "yImev SoH taH rur lIj vavpu', Daq 'Iv the former leghwI'pu' proclaimed, ja'ta': Thus jatlhtaH joH'a' vo' Armies, ‘chegh DaH vo' lIj mIghtaHghach Hemey, je vo' lIj mIghtaHghach ta'mey;' 'ach chaH ta'ta' ghobe' Qoy, ghobe' 'Ij Daq jIH, jatlhtaH joH'a'.",
        5: "lIj vavpu', nuqDaq 'oH chaH? je the leghwI'pu', ta' chaH yIn reH?",
        6: "'ach wIj mu'mey je wIj decrees, nuq jIH ra'ta' wIj toy'wI'pu' the leghwI'pu', ta'be' chaH overtake lIj vavpu'? “vaj chaH repented je ja'ta', ‘Just as joH'a' vo' Armies determined Daq ta' Daq maH, according Daq maj Hemey, je according Daq maj practices, vaj ghaH ghajtaH dealt tlhej maH.'”",
        7: "Daq the cha'maH-fourth jaj vo' the eleventh jar, nuq ghaH the jar Shebat, Daq the cha'DIch DIS vo' Darius, the mu' vo' joH'a' ghoSta' Daq Zechariah the puqloD vo' Berechiah, the puqloD vo' Iddo, the leghwI'pu', ja'ta',",
        8: "“jIH ghajta' a leghtaHghach Daq the ram, je yIlegh, a loD riding Daq a Doq horse, je ghaH Qampu' among the myrtle Sormey vetlh were Daq a ravine; je behind ghaH pa' were Doq, brown, je chIS horses.",
        9: "vaj jIH tlhobta', ‘wIj joH, nuq 'oH Dochvammey?'” The Duy 'Iv talked tlhej jIH ja'ta' Daq jIH, “jIH DichDaq cha' SoH nuq Dochvammey 'oH.”",
        10: "The loD 'Iv Qampu' among the myrtle Sormey jangta', “chaH 'oH the ones joH'a' ghajtaH ngeHta' Daq jaH DoH je vo' vegh the tera'.”",
        11: "chaH reported Daq the Duy vo' joH'a' 'Iv Qampu' among the myrtle Sormey, je ja'ta', “maH ghaj yItta' DoH je vo' vegh the tera', je yIlegh, Hoch the tera' ghaH Daq leS je Daq roj.”",
        12: "vaj the Duy vo' joH'a' replied, “toH joH'a' vo' Armies, chay' tIq DichDaq SoH ghobe' ghaj pung Daq Jerusalem je Daq the vengmey vo' Judah, Daq nuq SoH ghaj ghajta' indignation Dochvammey seventy DISmey?”",
        13: "joH'a' jangta' the Duy 'Iv talked tlhej jIH tlhej kind je comforting mu'mey.",
        14: "vaj the Duy 'Iv talked tlhej jIH ja'ta' Daq jIH, “Proclaim, ja'ta', ‘Thus jatlhtaH joH'a' vo' Armies: “jIH 'oH jealous vaD Jerusalem je vaD Zion tlhej a Dun jealousy.",
        15: "jIH 'oH very angry tlhej the tuqpu' vetlh 'oH Daq leSchu'; vaD jIH ghaHta' 'ach a mach displeased, 'ach chaH chelta' Daq the calamity.”",
        16: "vaj thus jatlhtaH joH'a': “jIH ghaj cheghta' Daq Jerusalem tlhej pung. wIj tuq DIchDaq taH chenta' Daq 'oH,” jatlhtaH joH'a' vo' Armies, “je a tlhegh DIchDaq taH stretched vo' Dung Jerusalem.”'",
        17: "“Proclaim further, ja'ta', ‘Thus jatlhtaH joH'a' vo' Armies: “wIj vengmey DichDaq again overflow tlhej mIp, je joH'a' DichDaq again belmoH Zion, je DichDaq again choose Jerusalem.”'”",
        18: "jIH qengta' Dung wIj mInDu', je leghta', je yIlegh, loS horns.",
        19: "jIH tlhobta' the Duy 'Iv talked tlhej jIH, “nuq 'oH Dochvammey?” ghaH jangta' jIH, “Dochvammey 'oH the horns nuq ghaj scattered Judah, Israel, je Jerusalem.”",
        20: "joH'a' showed jIH loS craftsmen.",
        21: "vaj jIH tlhobta', “nuq 'oH Dochvammey choltaH Daq ta'?” ghaH ja'ta', “Dochvammey 'oH the horns nuq scattered Judah, vaj vetlh ghobe' loD qengta' Dung Daj nach; 'ach Dochvammey ghaj ghoS Daq terrify chaH, Daq chuH bIng the horns vo' the tuqpu', nuq qengta' Dung chaj horn Daq the puH vo' Judah Daq scatter 'oH.”",
    },
    2: {
        1: "jIH qengta' Dung wIj mInDu', je leghta', je yIlegh, a loD tlhej a measuring tlhegh Daq Daj ghop.",
        2: "vaj jIH tlhobta', “nuqDaq 'oH SoH ghoS?” ghaH ja'ta' Daq jIH, “Daq juv Jerusalem, Daq legh nuq ghaH its breadth je nuq ghaH its length.”",
        3: "yIlegh, the Duy 'Iv talked tlhej jIH mejta' vo', je another Duy mejta' pa' Daq ghom ghaH,",
        4: "je ja'ta' Daq ghaH, “Run, jatlh Daq vam Qup loD, ja'ta', ‘Jerusalem DichDaq taH inhabited as villages Hutlh walls, because vo' the qevmey vo' loDpu' je livestock Daq 'oH.",
        5: "vaD jIH,' jatlhtaH joH'a', ‘DichDaq taH Daq Daj a reD vo' qul around 'oH, je jIH DichDaq taH the batlh Daq the midst vo' Daj.",
        6: "ghoS! ghoS! Haw' vo' the puH vo' the pemHov nIH,' jatlhtaH joH'a'; ‘vaD jIH ghaj ngeH SoH abroad as the loS winds vo' the sky,' jatlhtaH joH'a'.",
        7: "‘ghoS, Zion! Escape, SoH 'Iv yIn tlhej the puqbe' vo' Babylon.'",
        8: "vaD thus jatlhtaH joH'a' vo' Armies: ‘vaD quv ghaH ghajtaH ngeHta' jIH Daq the tuqpu' nuq plundered SoH; vaD ghaH 'Iv touches SoH touches the apple vo' Daj mIn.",
        9: "vaD, yIlegh, jIH DichDaq shake wIj ghop Dung chaH, je chaH DichDaq taH a non Daq chaH 'Iv served chaH; je SoH DichDaq Sov vetlh joH'a' vo' Armies ghajtaH ngeHta' jIH.",
        10: "bom je yItIv, puqbe' vo' Zion; vaD, yIlegh, jIH ghoS, je jIH DichDaq yIn Daq the midst vo' SoH,' jatlhtaH joH'a'.",
        11: "law' tuqpu' DIchDaq join themselves Daq joH'a' Daq vetlh jaj, je DIchDaq taH wIj ghotpu; je jIH DichDaq yIn Daq the midst vo' SoH, je SoH DIchDaq Sov vetlh joH'a' vo' Armies ghajtaH ngeHta' jIH Daq SoH.",
        12: "joH'a' DichDaq inherit Judah as Daj portion Daq the le' puH, je DichDaq again choose Jerusalem.",
        13: "taH tam, Hoch ghab, qaSpa' joH'a'; vaD ghaH ghajtaH roused himself vo' Daj le' juH!”",
    },
    3: {
        1: "ghaH showed jIH Joshua the jen lalDan vumwI' standing qaSpa' the Duy vo' joH'a', je Satan standing Daq Daj nIH ghop Daq taH Daj jagh.",
        2: "joH'a' ja'ta' Daq Satan, “joH'a' rebuke SoH, Satan! HIja', joH'a' 'Iv ghajtaH wIvpu' Jerusalem rebuke SoH! 'oHbe' vam a burning stick plucked pa' vo' the qul?”",
        3: "DaH Joshua ghaHta' clothed tlhej filthy garments, je ghaHta' standing qaSpa' the Duy.",
        4: "ghaH jangta' je jatlhta' Daq chaH 'Iv Qampu' qaSpa' ghaH, ja'ta', “tlhap the filthy garments litHa' vo' ghaH.” Daq ghaH ghaH ja'ta', “yIlegh, jIH ghaj caused lIj He'taHghach Daq juS vo' SoH, je jIH DichDaq clothe SoH tlhej rich Sut.”",
        5: "jIH ja'ta', “chaw' chaH cher a Say turban Daq Daj nach.” vaj chaH cher a Say turban Daq Daj nach, je clothed ghaH; je the Duy vo' joH'a' ghaHta' standing Sum.",
        6: "The Duy vo' joH'a' protested Daq Joshua, ja'ta',",
        7: "“Thus jatlhtaH joH'a' vo' Armies: ‘chugh SoH DichDaq yIt Daq wIj Hemey, je chugh SoH DichDaq tlha' wIj instructions, vaj SoH je DIchDaq noH wIj tuq, je DIchDaq je pol wIj bo'DIjmey, je jIH DichDaq nob SoH a Daq vo' access among Dochvammey 'Iv Qam Sum.",
        8: "Qoy DaH, Joshua the jen lalDan vumwI', SoH je lIj fellows 'Iv ba' qaSpa' SoH; vaD chaH 'oH loDpu' 'Iv 'oH a sign: vaD, yIlegh, jIH DichDaq qem vo' wIj toy'wI', the Branch.",
        9: "vaD, yIlegh, the nagh vetlh jIH ghaj cher qaSpa' Joshua; Daq wa' nagh 'oH Soch mInDu': yIlegh, jIH DichDaq engrave its engraving,' jatlhtaH joH'a' vo' Armies, ‘je jIH DichDaq teq the He'taHghach vo' vetlh puH Daq wa' jaj.",
        10: "Daq vetlh jaj,' jatlhtaH joH'a' vo' Armies, ‘SoH DichDaq invite Hoch loD Daj jIl bIng the vine je bIng the fig Sor.'”",
    },
    4: {
        1: "The Duy 'Iv talked tlhej jIH ghoSta' again, je wakened jIH, as a loD 'Iv ghaH wakened pa' vo' Daj Qong.",
        2: "ghaH ja'ta' Daq jIH, “nuq ta' SoH legh?” jIH ja'ta', “jIH ghaj leghpu', je yIlegh, a lampstand Hoch vo' SuD baS, tlhej its bowl Daq the top vo' 'oH, je its Soch lamps thereon; pa' 'oH Soch pipes Daq each vo' the lamps, nuq 'oH Daq the top vo' 'oH;",
        3: "je cha' olive Sormey Sum 'oH, wa' Daq the nIH retlh vo' the bowl, je the latlh Daq the poS retlh vo' 'oH.”",
        4: "jIH jangta' je jatlhta' Daq the Duy 'Iv talked tlhej jIH, ja'ta', “nuq 'oH Dochvammey, wIj joH?”",
        5: "vaj the Duy 'Iv talked tlhej jIH jangta' jIH, “yImev SoH Sov nuq Dochvammey 'oH?” jIH ja'ta', “ghobe', wIj joH.”",
        6: "vaj ghaH jangta' je jatlhta' Daq jIH, ja'ta', “vam ghaH the mu' vo' joH'a' Daq Zerubbabel, ja'ta', ‘ghobe' Sum might, ghobe' Sum HoS, 'ach Sum wIj qa',' jatlhtaH joH'a' vo' Armies.",
        7: "'Iv 'oH SoH, Dun HuD? qaSpa' Zerubbabel SoH 'oH a plain; je ghaH DichDaq qem pa' the capstone tlhej jach vo' ‘Grace, grace, Daq 'oH!'”",
        8: "Moreover the mu' vo' joH'a' ghoSta' Daq jIH, ja'ta',",
        9: "“The ghopmey vo' Zerubbabel ghaj laid the foundation vo' vam tuq. Daj ghopmey DIchDaq je finish 'oH; je SoH DichDaq Sov vetlh joH'a' vo' Armies ghajtaH ngeHta' jIH Daq SoH.",
        10: "Indeed, 'Iv despises the jaj vo' mach Dochmey? vaD Dochvammey Soch DIchDaq yItIv, je DIchDaq legh the plumb tlhegh Daq the ghop vo' Zerubbabel. Dochvammey 'oH the mInDu' vo' joH'a', nuq run DoH je vo' vegh the Hoch tera'.”",
        11: "vaj jIH tlhobta' ghaH, “nuq 'oH Dochvammey cha' olive Sormey Daq the nIH retlh vo' the lampstand je Daq the poS retlh vo' 'oH?”",
        12: "jIH tlhobta' ghaH the cha'DIch poH, “nuq 'oH Dochvammey cha' olive branches, nuq 'oH retlh the cha' golden spouts, vetlh pour the golden Hergh pa' vo' themselves?”",
        13: "ghaH jangta' jIH, “yImev SoH Sov nuq Dochvammey 'oH?” jIH ja'ta', “ghobe', wIj joH.”",
        14: "vaj ghaH ja'ta', “Dochvammey 'oH the cha' ngoHta' ones 'Iv Qam Sum the joH vo' the Hoch tera'.”",
    },
    5: {
        1: "vaj again jIH qengta' Dung wIj mInDu', je leghta', je yIlegh, a flying scroll.",
        2: "ghaH ja'ta' Daq jIH, “nuq ta' SoH legh?” jIH jangta', “jIH legh a flying scroll; its length ghaH cha'maH cubits, je its breadth wa'maH cubits.”",
        3: "vaj ghaH ja'ta' Daq jIH, “vam ghaH the mu'qaD vetlh goes pa' Dung the surface vo' the Hoch puH; vaD Hoch 'Iv steals DIchDaq taH pe' litHa' according Daq 'oH Daq the wa' retlh; je Hoch 'Iv swears falsely DIchDaq taH pe' litHa' according Daq 'oH Daq the latlh retlh.",
        4: "jIH DichDaq cause 'oH Daq jaH pa',” jatlhtaH joH'a' vo' Armies, “je 'oH DichDaq 'el Daq the tuq vo' the thief, je Daq the tuq vo' ghaH 'Iv swears falsely Sum wIj pong; je 'oH DichDaq remain Daq the midst vo' Daj tuq, je DichDaq Qaw' 'oH tlhej its timber je its naghmey.”",
        5: "vaj the Duy 'Iv talked tlhej jIH ghoSta' forward, je ja'ta' Daq jIH, “Lift Dung DaH lIj mInDu', je legh nuq ghaH vam vetlh ghaH appearing.”",
        6: "jIH ja'ta', “nuq ghaH 'oH?” ghaH ja'ta', “vam ghaH the ephah { Note: An ephah ghaH a juv vo' volume vo' about 22 litres, 5.8 U. S. gallons, joq about 2/3 vo' a bushel. } basket vetlh ghaH appearing.” ghaH ja'ta' moreover, “vam ghaH chaj appearance Daq Hoch the puH",
        7: "(je yIlegh, a talent { Note: A talent ghaH a weight vo' about 34 kilograms joq 75 pounds. } vo' Dev ghaHta' qengta' Dung); je vam ghaH a be' sitting Daq the midst vo' the ephah basket.”",
        8: "ghaH ja'ta', “vam ghaH mIghtaHghach;” je ghaH threw Daj bIng Daq the midst vo' the ephah basket; je ghaH threw the weight vo' Dev Daq its nujDu'.",
        9: "vaj qengta' jIH Dung wIj mInDu', je leghta', je yIlegh, pa' were cha' be'pu', je the SuS ghaHta' Daq chaj telDu'. DaH chaH ghajta' telDu' rur the telDu' vo' a stork, je chaH qengta' Dung the ephah basket joj tera' je the sky.",
        10: "vaj ja'ta' jIH Daq the Duy 'Iv talked tlhej jIH, “nuqDaq 'oH Dochvammey carrying the ephah basket?”",
        11: "ghaH ja'ta' Daq jIH, “Daq chen Daj a tuq Daq the puH vo' Shinar. ghorgh 'oH ghaH prepared, ghaH DichDaq taH cher pa' Daq Daj ghaj Daq.”",
    },
    6: {
        1: "Again jIH qengta' Dung wIj mInDu', je leghta', je yIlegh, loS Dujmey ghoSta' pa' vo' joj cha' Hudmey; je the Hudmey were Hudmey vo' brass.",
        2: "Daq the wa'Dich chariot were Doq horses; Daq the cha'DIch chariot black horses;",
        3: "Daq the wejDIch chariot chIS horses; je Daq the fourth chariot dappled horses, Hoch vo' chaH powerful.",
        4: "vaj jIH tlhobta' the Duy 'Iv talked tlhej jIH, “nuq 'oH Dochvammey, wIj joH?”",
        5: "The Duy jangta' jIH, “Dochvammey 'oH the loS winds vo' the sky, nuq jaH vo' vo' standing qaSpa' the joH vo' Hoch the tera'.",
        6: "The wa' tlhej the black horses goes pa' toward the pemHov nIH Hatlh; je the chIS mejta' pa' after chaH; je the dappled mejta' vo' toward the pemHov poS Hatlh.”",
        7: "The HoS mejta' pa', je nejta' Daq jaH vetlh chaH might yIt DoH je vo' vegh the tera': je ghaH ja'ta', “jaH around je vegh the tera'!” vaj chaH yItta' DoH je vo' vegh the tera'.",
        8: "vaj ghaH ja' Daq jIH, je jatlhta' Daq jIH, ja'ta', “yIlegh, chaH 'Iv jaH toward the pemHov nIH Hatlh ghaj quieted wIj qa' Daq the pemHov nIH Hatlh.”",
        9: "The mu' vo' joH'a' ghoSta' Daq jIH, ja'ta',",
        10: "“tlhap vo' chaH vo' the captivity, 'ach vo' Heldai, vo' Tobijah, je vo' Jedaiah; je ghoS the rap jaj, je jaH Daq the tuq vo' Josiah the puqloD vo' Zephaniah, nuqDaq chaH ghaj ghoS vo' Babylon.",
        11: "HIja', tlhap baS chIS je SuD baS, je chenmoH crowns, je cher chaH Daq the nach vo' Joshua the puqloD vo' Jehozadak, the jen lalDan vumwI';",
        12: "je jatlh Daq ghaH, ja'ta', ‘Thus jatlhtaH joH'a' vo' Armies, “yIlegh, the loD 'Iv pong ghaH the Branch: je ghaH DIchDaq grow Dung pa' vo' Daj Daq; je ghaH DIchDaq chen the lalDan qach vo' joH'a';",
        13: "'ach ghaH DIchDaq chen the lalDan qach vo' joH'a'; je ghaH DIchDaq SIQ the batlh, je DIchDaq ba' je rule Daq Daj quS'a'; je ghaH DIchDaq taH a lalDan vumwI' Daq Daj quS'a'; je the qeS vo' roj DIchDaq taH joj chaH both.",
        14: "The crowns DIchDaq taH Daq Helem, je Daq Tobijah, je Daq Jedaiah, je Daq Hen the puqloD vo' Zephaniah, vaD a memorial Daq the lalDan qach vo' joH'a'.",
        15: "chaH 'Iv 'oH Hop litHa' DIchDaq ghoS je chen Daq the lalDan qach vo' joH'a'; je SoH DIchDaq Sov vetlh joH'a' vo' Armies ghajtaH ngeHta' jIH Daq SoH. vam DichDaq qaS, chugh SoH DichDaq diligently obey the ghogh vo' joH'a' lIj joH'a'.”'”",
    },
    7: {
        1: "'oH qaSta' Daq the fourth DIS vo' joH Darius vetlh the mu' vo' joH'a' ghoSta' Daq Zechariah Daq the fourth jaj vo' the ninth jar, the jar vo' Chislev.",
        2: "The ghotpu vo' Bethel ngeHta' Sharezer je Regem Melech, je chaj loDpu', Daq entreat joH'a' favor,",
        3: "je Daq jatlh Daq the lalDan vumwI'pu' vo' the tuq vo' joH'a' vo' Armies, je Daq the leghwI'pu', ja'ta', “Should jIH weep Daq the fifth jar, separating jIH'egh, as jIH ghaj ta'pu' Dochvammey vaj law' DISmey?”",
        4: "vaj the mu' vo' joH'a' vo' Armies ghoSta' Daq jIH, ja'ta',",
        5: "“jatlh Daq Hoch the ghotpu vo' the puH, je Daq the lalDan vumwI'pu', ja'ta', ‘ghorgh SoH fasted je mourned Daq the fifth je Daq the SochDIch jar vaD Dochvammey seventy DISmey, ta'ta' SoH Daq Hoch fast Daq jIH, really Daq jIH?",
        6: "ghorgh SoH Sop, je ghorgh SoH tlhutlh, yImev SoH Sop vaD tlhIH'egh, je tlhutlh vaD tlhIH'egh?",
        7: "Aren't Dochvammey the mu'mey nuq joH'a' proclaimed Sum the former leghwI'pu', ghorgh Jerusalem ghaHta' inhabited je Daq mIp, je its vengmey around Daj, je the pemHov poS je the lowland were inhabited?'”",
        8: "The mu' vo' joH'a' ghoSta' Daq Zechariah, ja'ta',",
        9: "“Thus ghajtaH joH'a' vo' Armies jatlhpu', ja'ta', ‘Execute true yoj, je cha' pung je compassion Hoch loD Daq Daj loDnI'.",
        10: "yImev oppress the Heghbe'nal, ghobe' the vav ghajbe', the foreigner, ghobe' the mIpHa'; je chaw' pagh vo' SoH devise mIghtaHghach Daq Daj loDnI' Daq lIj tIq.'",
        11: "'ach chaH refused Daq 'Ij, je tlhe'ta' chaj backs, je stopped chaj qoghDu', vetlh chaH might ghobe' Qoy.",
        12: "HIja', chaH chenmoHta' chaj tIQDu' as hard as flint, lest chaH might Qoy the chut, je the mu'mey nuq joH'a' vo' Armies ghajta' ngeHta' Sum Daj qa' Sum the former leghwI'pu'. vaj Dun QeHpu' ghoSta' vo' joH'a' vo' Armies.",
        13: "'oH ghajtaH ghoS Daq juS vetlh, as ghaH ja', je chaH refused Daq 'Ij, vaj chaH DichDaq ja', je jIH DichDaq ghobe' 'Ij,” ja'ta' joH'a' vo' Armies;",
        14: "“'ach jIH DichDaq scatter chaH tlhej a whirlwind among Hoch the tuqpu' nuq chaH ghaj ghobe' Sovta'. Thus the puH ghaHta' moB after chaH, vaj vetlh ghobe' loD juSta' vegh ghobe' cheghta': vaD chaH chenmoHta' the bel puH moB.”",
    },
    8: {
        1: "The mu' vo' joH'a' vo' Armies ghoSta' Daq jIH.",
        2: "Thus jatlhtaH joH'a' vo' Armies: “jIH 'oH jealous vaD Zion tlhej Dun jealousy, je jIH 'oH jealous vaD Daj tlhej Dun QeHpu'.”",
        3: "Thus jatlhtaH joH'a': “jIH ghaj cheghta' Daq Zion, je DichDaq yIn Daq the midst vo' Jerusalem. Jerusalem DIchDaq taH ja' ‘The veng vo' vIt;' je the HuD vo' joH'a' vo' Armies, ‘The le' HuD.'”",
        4: "Thus jatlhtaH joH'a' vo' Armies: “qan loDpu' je qan be'pu' DichDaq again yIn Daq the streets vo' Jerusalem, Hoch loD tlhej Daj naQ Daq Daj ghop vaD very age.",
        5: "The streets vo' the veng DichDaq taH teblu'ta' vo' boys je girls playing Daq its streets.”",
        6: "Thus jatlhtaH joH'a' vo' Armies: “chugh 'oH ghaH marvelous Daq the mInDu' vo' the chuv vo' vam ghotpu Daq chaH jajmey, should 'oH je taH marvelous Daq wIj mInDu'?” jatlhtaH joH'a' vo' Armies.",
        7: "Thus jatlhtaH joH'a' vo' Armies: “yIlegh, jIH DichDaq toD wIj ghotpu vo' the pemHov 'o' Hatlh, je vo' the pemHov 'et Hatlh;",
        8: "je jIH DichDaq qem chaH, je chaH DichDaq yIn Daq the midst vo' Jerusalem; je chaH DichDaq taH wIj ghotpu, je jIH DichDaq taH chaj joH'a', Daq vIt je Daq QaQtaHghach.”",
        9: "Thus jatlhtaH joH'a' vo' Armies: “chaw' lIj ghopmey taH HoS, SoH 'Iv Qoy Daq Dochvammey jajmey Dochvammey mu'mey vo' the nujDu' vo' the leghwI'pu' 'Iv were Daq the jaj vetlh the foundation vo' the tuq vo' joH'a' vo' Armies ghaHta' laid, 'ach the lalDan qach, vetlh 'oH might taH chenta'.",
        10: "vaD qaSpa' chaH jajmey pa' ghaHta' ghobe' wages vaD loD, ghobe' vay' wages vaD an animal; ghobe' ghaHta' pa' vay' roj Daq ghaH 'Iv mejta' pa' joq ghoSta' Daq, because vo' the jagh. vaD jIH cher Hoch loDpu' Hoch Daq Daj jIl.",
        11: "'ach DaH jIH DichDaq ghobe' taH Daq the chuv vo' vam ghotpu as Daq the former jajmey,” jatlhtaH joH'a' vo' Armies.",
        12: "“vaD the tIr vo' roj je the vine DichDaq yield its baQ, je the yav DichDaq nob its increase, je the chal DichDaq nob chaj dew; je jIH DichDaq cause the chuv vo' vam ghotpu Daq inherit Hoch Dochvammey Dochmey.",
        13: "'oH DIchDaq ghoS Daq juS vetlh, as SoH were a mu'qaD among the tuqpu', tuq vo' Judah je tuq vo' Israel, vaj DichDaq jIH toD SoH, je SoH DIchDaq taH a blessing. yImev taH vIp. chaw' lIj ghopmey taH HoS.”",
        14: "vaD thus jatlhtaH joH'a' vo' Armies: “As jIH thought Daq ta' mIghtaHghach Daq SoH, ghorgh lIj vavpu' provoked jIH Daq QeHpu',” jatlhtaH joH'a' vo' Armies, “je jIH ta'be' repent;",
        15: "vaj again ghaj jIH thought Daq Dochvammey jajmey Daq ta' QaQ Daq Jerusalem je Daq the tuq vo' Judah. yImev taH vIp.",
        16: "Dochvammey 'oH the Dochmey vetlh SoH DIchDaq ta': jatlh Hoch loD the vIt tlhej Daj jIl. Execute the yoj vo' vIt je roj Daq lIj lojmItmey,",
        17: "je chaw' pagh vo' SoH devise mIghtaHghach Daq lIj tIQDu' Daq Daj jIl, je muSHa' ghobe' false oath: vaD Hoch Dochvammey 'oH Dochmey vetlh jIH hate,” jatlhtaH joH'a'.",
        18: "The mu' vo' joH'a' vo' Armies ghoSta' Daq jIH.",
        19: "Thus jatlhtaH joH'a' vo' Armies: “The fasts vo' the fourth fifth, SochDIch, je tenth months DIchDaq taH vaD the tuq vo' Judah Quch je Quchqu'taHghach, je cheerful yupma'mey. vaj muSHa' vIt je roj.”",
        20: "Thus jatlhtaH joH'a' vo' Armies: “law' ghotpu', je the nganpu' vo' law' vengmey DichDaq yet ghoS;",
        21: "je the nganpu' vo' wa' DIchDaq jaH Daq another, ja'ta', ‘chaw' maH jaH speedily Daq entreat the favor vo' joH'a', je Daq nej joH'a' vo' Armies. jIH DichDaq jaH je.'",
        22: "HIja', law' ghotpu' je HoS tuqpu' DichDaq ghoS Daq nej joH'a' vo' Armies Daq Jerusalem, je Daq entreat the favor vo' joH'a'.”",
        23: "Thus jatlhtaH joH'a' vo' Armies: “Daq chaH jajmey, wa'maH loDpu' DichDaq tlhap 'uch, pa' vo' Hoch the languages vo' the tuqpu', chaH DichDaq tlhap 'uch vo' the skirt vo' ghaH 'Iv ghaH a Jew, ja'ta', ‘maH DichDaq jaH tlhej SoH, vaD maH ghaj Qoyta' vetlh joH'a' ghaH tlhej SoH.'”",
    },
    9: {
        1: "An oracle. The mu' vo' joH'a' ghaH Daq the puH vo' Hadrach, je DichDaq leS upon Damascus; vaD the mIn vo' loD je vo' Hoch the tuqpu' vo' Israel ghaH toward joH'a';",
        2: "je Hamath, je, nuq veHmey Daq 'oH; Tyre je Sidon, because chaH 'oH very val.",
        3: "Tyre chenta' herself a stronghold, je heaped Dung baS chIS rur the dust, je fine SuD baS rur the mire vo' the streets.",
        4: "yIlegh, the joH DichDaq dispossess Daj, je ghaH DichDaq mup Daj HoS Daq the biQ'a'; je ghaH DichDaq taH Soppu' tlhej qul.",
        5: "Ashkelon DichDaq legh 'oH, je taHvIp; Gaza je, je DichDaq writhe Daq agony; as DichDaq Ekron, vaD Daj expectation DichDaq taH disappointed; je the joH DichDaq chIlqu' vo' Gaza, je Ashkelon DichDaq ghobe' taH inhabited.",
        6: "Foreigners DichDaq yIn Daq Ashdod, je jIH DichDaq pe' litHa' the pride vo' the Philistines.",
        7: "jIH DichDaq tlhap DoH Daj 'Iw pa' vo' Daj nujDu', je Daj qabqu'boghghachmey vo' joj Daj teeth; je ghaH je DichDaq taH a chuv vaD maj joH'a'; je ghaH DichDaq taH as a chieftain Daq Judah, je Ekron as a Jebusite.",
        8: "jIH DichDaq Dab around wIj tuq Daq the army, vetlh pagh juS vegh joq chegh; je ghobe' oppressor DichDaq juS vegh chaH vay' latlh: vaD DaH jIH ghaj leghpu' tlhej wIj mInDu'.",
        9: "yItIv greatly, puqbe' vo' Zion! jach, puqbe' vo' Jerusalem! yIlegh, lIj joH choltaH Daq SoH! ghaH ghaH QaQtaHghach, je ghajtaH toDtaHghach; lowly, je riding Daq a SarghHom, 'ach Daq a colt, the foal vo' a SarghHom.",
        10: "jIH DichDaq pe' litHa' the chariot vo' Ephraim, je the horse vo' Jerusalem; je the may' bow DichDaq taH pe' litHa'; je ghaH DichDaq jatlh roj Daq the tuqpu': je Daj dominion DichDaq taH vo' biQ'a' Daq biQ'a', je vo' the bIQtIQ Daq the ends vo' the tera'.",
        11: "As vaD SoH je, because vo' the 'Iw vo' lIj lay', jIH ghaj cher free lIj prisoners vo' the pit Daq nuq ghaH ghobe' bIQ.",
        12: "tlhe' Daq the stronghold, SoH prisoners vo' tul! 'ach DaHjaj jIH declare vetlh jIH DichDaq nobHa' double Daq SoH.",
        13: "vaD indeed jIH SIH Judah as a bow vaD jIH. jIH ghaj tebta' the bow tlhej Ephraim; je jIH DichDaq stir Dung lIj puqloDpu', Zion, Daq lIj puqloDpu', Greece, je DichDaq chenmoH SoH rur the 'etlh vo' a HoS loD.",
        14: "joH'a' DichDaq taH leghpu' Dung chaH; je Daj puv DuQwI' DichDaq jaH flash rur lightning; je the joH joH'a' DichDaq blow the trumpet, je DichDaq jaH tlhej whirlwinds vo' the pemHov poS.",
        15: "joH'a' vo' Armies DichDaq defend chaH; je chaH DichDaq Qaw' je overcome tlhej sling naghmey; je chaH DichDaq tlhutlh, je roar as vegh HIq; je chaH DichDaq taH tebta' rur bowls, rur the corners vo' the lalDanta' Daq.",
        16: "joH'a' chaj joH'a' DichDaq toD chaH Daq vetlh jaj as the flock vo' Daj ghotpu; vaD chaH 'oH rur the jewels vo' a crown, qengta' Daq jen Dung Daj puH.",
        17: "vaD chay' Dun ghaH Daj QaQ, je chay' Dun ghaH Daj 'IhtaHghach! Grain DichDaq chenmoH the Qup loDpu' flourish, je chu' HIq the virgins.",
    },
    10: {
        1: "tlhob vo' joH'a' rain Daq the spring poH, joH'a' 'Iv chen storm clouds, je ghaH nob rain showers Daq Hoch vaD the plants Daq the yotlh.",
        2: "vaD the teraphim ghaj jatlhpu' vanity, je the diviners ghaj leghpu' a Qot; je chaH ghaj ja'ta' false dreams. chaH belmoH Daq lI'be'. vaj chaH jaH chaj way rur Suy'. chaH 'oH Suvta', because pa' ghaH ghobe' DevwI'.",
        3: "wIj QeH ghaH kindled Daq the shepherds, je jIH DichDaq punish the male goats; vaD joH'a' vo' Armies ghajtaH visited Daj flock, the tuq vo' Judah, je DichDaq chenmoH chaH as Daj majestic horse Daq the may'.",
        4: "vo' ghaH DichDaq ghoS vo' the cornerstone, vo' ghaH the nail, vo' ghaH the may' bow, vo' ghaH Hoch ruler tay'.",
        5: "chaH DIchDaq taH as HoS loDpu', treading bIng muddy streets Daq the may'; je chaH DIchDaq Suv, because joH'a' ghaH tlhej chaH; je the riders Daq horses DichDaq taH mISmoHpu'.",
        6: "“jIH DichDaq strengthen the tuq vo' Judah, je jIH DichDaq toD the tuq vo' Joseph, je jIH DichDaq qem chaH DoH; vaD jIH ghaj pung Daq chaH; je chaH DichDaq taH as 'a' jIH ghajta' ghobe' chuH chaH litHa': vaD jIH 'oH joH'a' chaj joH'a', je jIH DichDaq Qoy chaH.",
        7: "Ephraim DichDaq taH rur a HoS loD, je chaj tIq DichDaq yItIv as vegh HIq; HIja', chaj puqpu' DichDaq legh 'oH, je yItIv. chaj tIq DichDaq taH Quchqu' Daq joH'a'.",
        8: "jIH DichDaq signal vaD chaH, je tay'moH chaH; vaD jIH ghaj toDta' chaH; je chaH DichDaq increase as chaH ghaj increased.",
        9: "jIH DichDaq sow chaH among the ghotpu'; je chaH DichDaq qaw jIH Daq Hop countries; je chaH DichDaq yIn tlhej chaj puqpu', je DichDaq chegh.",
        10: "jIH DichDaq qem chaH again je pa' vo' the puH vo' Egypt, je tay'moH chaH pa' vo' Assyria; je jIH DichDaq qem chaH Daq the puH vo' Gilead je Lebanon; je pa' won't taH room yap vaD chaH.",
        11: "ghaH DichDaq juS vegh the biQ'a' vo' affliction, je DichDaq mup the waves Daq the biQ'a', je Hoch the depths vo' the Nile DichDaq dry Dung; je the pride vo' Assyria DichDaq taH qempu' bIng, je the scepter vo' Egypt DichDaq mej.",
        12: "jIH DichDaq strengthen chaH Daq joH'a'; je chaH DichDaq yIt Dung je bIng Daq Daj pong,” jatlhtaH joH'a'.",
    },
    11: {
        1: 'poSmoH lIj doors, Lebanon, vetlh the qul may Sop lIj cedars.',
        2: "Wail, fir Sor, vaD the cedar ghajtaH fallen, because the stately ones 'oH Qaw'ta'. Wail, SoH Sor'a'mey vo' Bashan, vaD the HoS forest ghajtaH ghoS bIng.",
        3: "A ghogh vo' the wailing vo' the shepherds! vaD chaj batlh ghaH Qaw'ta': a ghogh vo' the roaring vo' Qup lions! vaD the pride vo' the Jordan ghaH ruined.",
        4: "Thus jatlhtaH joH'a' wIj joH'a': “Feed the flock vo' HoHqu'.",
        5: "chaj buyers HoHqu' chaH, je jaH unpunished. chaH 'Iv sell chaH jatlh, ‘ghurtaH taH joH'a', vaD jIH 'oH rich;' je chaj ghaj shepherds yImev pity chaH.",
        6: "vaD jIH DichDaq ghobe' latlh pity the nganpu' vo' the puH,” jatlhtaH joH'a'; “'ach, yIlegh, jIH DichDaq toD the loDpu' Hoch Daq Daj neighbor's ghop, je Daq the ghop vo' Daj joH. chaH DichDaq mup the puH, je pa' vo' chaj ghop jIH DichDaq ghobe' toD chaH.”",
        7: "vaj jIH Sopta' the flock vo' HoHqu', especially the Suvta' vo' the flock. jIH tlhapta' vaD jIH'egh cha' staffs. The wa' jIH ja' “Favor,” je the latlh jIH ja' “Union,” je jIH Sopta' the flock.",
        8: "jIH pe' litHa' the wej shepherds Daq wa' jar; vaD wIj qa' ghaHta' Doy' vo' chaH, je chaj qa' je loathed jIH.",
        9: "vaj jIH ja'ta', “jIH DichDaq ghobe' feed SoH. vetlh nuq dies, chaw' 'oH Hegh; je vetlh nuq ghaH Daq taH pe' litHa', chaw' 'oH taH pe' litHa'; je chaw' chaH 'Iv 'oH poS Sop each other's ghab.”",
        10: "jIH tlhapta' wIj naQ Favor, je pe' 'oH apart, vetlh jIH might ghor wIj lay' vetlh jIH ghajta' chenmoHta' tlhej Hoch the ghotpu'.",
        11: "'oH ghaHta' ghorta' Daq vetlh jaj; je thus the mIpHa' vo' the flock vetlh listened Daq jIH knew vetlh 'oH ghaHta' the mu' vo' joH'a'.",
        12: "jIH ja'ta' Daq chaH, “chugh SoH think 'oH best, nob jIH wIj wages; je chugh ghobe', pol chaH.” vaj chaH weighed vaD wIj wages wejmaH pieces vo' baS chIS.",
        13: "joH'a' ja'ta' Daq jIH, “Throw 'oH Daq the potter, the handsome price vetlh jIH ghaHta' valued Daq Sum chaH!” jIH tlhapta' the wejmaH pieces vo' baS chIS, je threw chaH Daq the potter, Daq the tuq vo' joH'a'.",
        14: "vaj jIH pe' apart wIj latlh naQ, 'ach Union, vetlh jIH might ghor the brotherhood joj Judah je Israel.",
        15: "joH'a' ja'ta' Daq jIH, “tlhap vaD SoH'egh yet again the equipment vo' a foolish DevwI'.",
        16: "vaD, yIlegh, jIH DichDaq raise Dung a DevwI' Daq the puH, 'Iv DichDaq ghobe' visit chaH 'Iv 'oH pe' litHa', ghobe' DichDaq nej chaH 'Iv 'oH scattered, ghobe' heal vetlh nuq ghaH ghorta', ghobe' feed vetlh nuq ghaH wab; 'ach ghaH DichDaq Sop the ghab vo' the ror Suy', je DichDaq tear chaj hoofs Daq pieces.",
        17: "Woe Daq the worthless DevwI' 'Iv leaves the flock! The 'etlh DichDaq taH Daq Daj arm, je Daq Daj nIH mIn. Daj arm DichDaq taH completely withered, je Daj nIH mIn DichDaq taH totally blinded!”",
    },
    12: {
        1: "An oracle. The mu' vo' joH'a' concerning Israel. joH'a', 'Iv stretches pa' the chal, je lays the foundation vo' the tera', je forms the qa' vo' loD within ghaH jatlhtaH:",
        2: "“yIlegh, jIH DichDaq chenmoH Jerusalem a HIvje' vo' reeling Daq Hoch the surrounding ghotpu', je Daq Judah je DichDaq 'oH taH Daq the siege Daq Jerusalem.",
        3: "'oH DichDaq qaS Daq vetlh jaj, vetlh jIH DichDaq chenmoH Jerusalem a burdensome nagh vaD Hoch the ghotpu'. Hoch 'Iv burden themselves tlhej 'oH DichDaq taH severely wounded, je Hoch the tuqpu' vo' the tera' DichDaq taH boSta' tay' Daq 'oH.",
        4: "Daq vetlh jaj,” jatlhtaH joH'a', “jIH DichDaq mup Hoch horse tlhej ghIjvIptaH, je Daj rider tlhej madness; je jIH DichDaq poSmoH wIj mInDu' Daq the tuq vo' Judah, je DichDaq mup Hoch horse vo' the ghotpu' tlhej blindness.",
        5: "The chieftains vo' Judah DichDaq jatlh Daq chaj tIq, ‘The nganpu' vo' Jerusalem 'oH wIj HoS Daq joH'a' vo' Armies chaj joH'a'.'",
        6: "Daq vetlh jaj jIH DichDaq chenmoH the chieftains vo' Judah rur a pan vo' qul among wood, je rur a flaming torch among sheaves; je chaH DichDaq Sop Hoch the surrounding ghotpu', Daq the nIH ghop je Daq the poS; je Jerusalem DichDaq yet again yIn Daq chaj ghaj Daq, 'ach Daq Jerusalem.",
        7: "joH'a' je DichDaq toD the tents vo' Judah wa'Dich, vetlh the batlh vo' the tuq vo' David je the batlh vo' the nganpu' vo' Jerusalem ghobe' taH magnified Dung Judah.",
        8: "Daq vetlh jaj joH'a' DichDaq defend the nganpu' vo' Jerusalem. ghaH 'Iv ghaH feeble among chaH Daq vetlh jaj DichDaq taH rur David, je the tuq vo' David DichDaq taH rur joH'a', rur the Duy vo' joH'a' qaSpa' chaH.",
        9: "'oH DichDaq qaS Daq vetlh jaj, vetlh jIH DichDaq nej Daq Qaw' Hoch the tuqpu' vetlh ghoS Daq Jerusalem.",
        10: "jIH DichDaq pour Daq the tuq vo' David, je Daq the nganpu' vo' Jerusalem, the qa' vo' grace je vo' supplication; je chaH DichDaq legh Daq jIH { Note: After “jIH,” the Hebrew ghajtaH the cha' letters “Aleph Tav” (the wa'Dich je last letters vo' the Hebrew alphabet), ghobe' as a mu', 'ach as a grammatical marker. } 'Iv chaH ghaj pierced; je chaH DIchDaq mourn vaD ghaH, as wa' mourns vaD Daj neH puqloD, je DichDaq grieve bitterly vaD ghaH, as wa' grieves vaD Daj firstborn.",
        11: "Daq vetlh jaj pa' DichDaq taH a Dun mourning Daq Jerusalem, rur the mourning vo' Hadadrimmon Daq the ngech vo' Megiddon.",
        12: "The puH DichDaq mourn, Hoch qorDu' apart; the qorDu' vo' the tuq vo' David apart, je chaj be'nalpu' apart; the qorDu' vo' the tuq vo' Nathan apart, je chaj be'nalpu' apart;",
        13: "the qorDu' vo' the tuq vo' Levi apart, je chaj be'nalpu' apart; the qorDu' vo' the Shimeites apart, je chaj be'nalpu' apart;",
        14: "Hoch the qorDu'pu' 'Iv remain, Hoch qorDu' apart, je chaj be'nalpu' apart.",
    },
    13: {
        1: "“Daq vetlh jaj pa' DichDaq taH a spring poSmaHpu' Daq the tuq vo' David je Daq the nganpu' vo' Jerusalem, vaD yem je vaD uncleanness.",
        2: "'oH DichDaq ghoS Daq juS Daq vetlh jaj, jatlhtaH joH'a' vo' Armies, vetlh jIH DichDaq pe' litHa' the pongmey vo' the idols pa' vo' the puH, je chaH DichDaq taH remembered ghobe' latlh. jIH DichDaq je cause the leghwI'pu' je the qa' vo' impurity Daq juS pa' vo' the puH.",
        3: "'oH DichDaq qaS vetlh, ghorgh anyone vIHHa' prophesies, vaj Daj vav je Daj SoS 'Iv boghmoH ghaH DichDaq ja' ghaH, ‘SoH must Hegh, because SoH jatlh lies Daq the pong vo' joH'a';' je Daj vav je Daj SoS 'Iv boghmoH ghaH DichDaq stab ghaH ghorgh ghaH prophesies.",
        4: "'oH DichDaq qaS Daq vetlh jaj, vetlh the leghwI'pu' DichDaq each taH tuH vo' Daj leghtaHghach, ghorgh ghaH prophesies; ghobe' DichDaq chaH wear a hairy mantle Daq deceive:",
        5: "'ach ghaH DichDaq jatlh, ‘jIH 'oH ghobe' leghwI'pu', jIH 'oH a tiller vo' the yav; vaD jIH ghaj taH chenmoHta' a bondservant vo' wIj youth.'",
        6: "wa' DichDaq jatlh Daq ghaH, ‘nuq 'oH Dochvammey QIDpu'ghachmey joj lIj arms?' vaj ghaH DichDaq jang, ‘chaH tlhej nuq jIH ghaHta' wounded Daq the tuq vo' wIj friends.'",
        7: "“Awake, 'etlh, Daq wIj DevwI', je Daq the loD 'Iv ghaH close Daq jIH,” jatlhtaH joH'a' vo' Armies. “mup the DevwI', je the Suy' DichDaq taH scattered; je jIH DichDaq tlhe' wIj ghop Daq the mach ones.",
        8: "'oH DIchDaq qaS vetlh Daq Hoch the puH,” jatlhtaH joH'a', “cha' parts Daq 'oH DichDaq taH pe' litHa' je Hegh; 'ach the wejDIch DichDaq taH poS Daq 'oH.",
        9: "jIH DichDaq qem the wejDIch part Daq the qul, je DichDaq refine chaH as baS chIS ghaH refined, je DichDaq test chaH rur SuD baS ghaH tested. chaH DichDaq ja' Daq wIj pong, je jIH DichDaq Qoy chaH. jIH DichDaq jatlh, ‘'oH ghaH wIj ghotpu;' je chaH DichDaq jatlh, ‘joH'a' ghaH wIj joH'a'.'”",
    },
    14: {
        1: "yIlegh, a jaj vo' joH'a' choltaH, ghorgh lIj non DichDaq taH divided Daq lIj midst.",
        2: "vaD jIH DichDaq tay'moH Hoch tuqpu' Daq Jerusalem Daq may'; je the veng DichDaq taH tlhappu', the juHmey rifled, je the be'pu' ravished. bID vo' the veng DichDaq jaH pa' Daq captivity, je the leS vo' the ghotpu DichDaq ghobe' taH pe' litHa' vo' the veng.",
        3: "vaj joH'a' DichDaq jaH pa' je Suv Daq chaH tuqpu', as ghorgh ghaH Suvta' Daq the jaj vo' may'.",
        4: "Daj qamDu' DichDaq Qam Daq vetlh jaj Daq the Mount vo' Olives, nuq ghaH qaSpa' Jerusalem Daq the pemHov 'o'; je the Mount vo' Olives DichDaq taH split Daq cha', vo' pemHov 'o' Daq pemHov 'et, making a very Dun ngech. bID vo' the HuD DichDaq vIH toward the pemHov nIH, je bID vo' 'oH toward the pemHov poS.",
        5: "SoH DIchDaq Haw' Sum the ngech vo' wIj Hudmey; vaD the ngech vo' the Hudmey DIchDaq reach Daq Azel; HIja', SoH DIchDaq Haw', just rur SoH Haw'ta' vo' qaSpa' the earthquake Daq the jajmey vo' Uzziah joH vo' Judah. joH'a' wIj joH'a' DichDaq ghoS, je Hoch the le' ones tlhej SoH.",
        6: "'oH DichDaq qaS Daq vetlh jaj, vetlh pa' DichDaq ghobe' taH wov, cold, joq frost.",
        7: "'oH DichDaq taH a unique jaj nuq ghaH Sovta' Daq joH'a'; ghobe' jaj, je ghobe' ram; 'ach 'oH DichDaq ghoS Daq juS, vetlh Daq evening poH pa' DichDaq taH wov.",
        8: "'oH DichDaq qaS Daq vetlh jaj, vetlh yIntaH bIQmey DichDaq jaH pa' vo' Jerusalem; bID vo' chaH toward the eastern biQ'a', je bID vo' chaH toward the western biQ'a'; Daq summer je Daq winter DichDaq 'oH taH.",
        9: "joH'a' DichDaq taH joH Dung Hoch the tera'. Daq vetlh jaj joH'a' DichDaq taH wa', je Daj pong wa'.",
        10: "Hoch the puH DichDaq taH chenmoHta' rur the Arabah, vo' Geba Daq Rimmon pemHov poS vo' Jerusalem; je ghaH DichDaq taH qengta' Dung, je DichDaq yIn Daq Daj Daq, vo' Benjamin's lojmIt Daq the Daq vo' the wa'Dich lojmIt, Daq the corner lojmIt, je vo' the tower vo' Hananel Daq the joH winepresses.",
        11: "loDpu' DichDaq yIn therein, je pa' DichDaq taH ghobe' latlh mu'qaD; 'ach Jerusalem DichDaq yIn safely.",
        12: "vam DichDaq taH the rop'a' tlhej nuq joH'a' DichDaq mup Hoch the ghotpu' 'Iv ghaj warred Daq Jerusalem: chaj ghab DichDaq consume DoH qaStaHvIS chaH Qam Daq chaj qamDu', je chaj mInDu' DichDaq consume DoH Daq chaj sockets, je chaj jat DichDaq consume DoH Daq chaj nujDu'.",
        13: "'oH DichDaq qaS Daq vetlh jaj, vetlh a Dun panic vo' joH'a' DichDaq taH among chaH; je chaH DichDaq lay 'uch Hoch Daq the ghop vo' Daj jIl, je Daj ghop DichDaq Hu' Dung Daq the ghop vo' Daj jIl.",
        14: "Judah je DichDaq Suv Daq Jerusalem; je the wealth vo' Hoch the surrounding tuqpu' DichDaq taH boSta' tay': SuD baS, je baS chIS, je Sut, Daq Dun abundance.",
        15: "vaj DichDaq taH the rop'a' vo' the horse, vo' the mule, vo' the camel, je vo' the SarghHom, je vo' Hoch the Ha'DIbaH vetlh DichDaq taH Daq chaH camps, as vetlh rop'a'.",
        16: "'oH DichDaq qaS vetlh Hoch 'Iv ghaH poS vo' Hoch the tuqpu' vetlh ghoSta' Daq Jerusalem DichDaq jaH Dung vo' DIS Daq DIS Daq lalDan toy' the joH, joH'a' vo' Armies, je Daq pol the 'uQ'a' vo' tents.",
        17: "'oH DichDaq taH, vetlh 'Iv vo' Hoch the qorDu'pu' vo' the tera' ta'be' jaH Dung Daq Jerusalem Daq lalDan toy' the joH, joH'a' vo' Armies, Daq chaH pa' DichDaq taH ghobe' rain.",
        18: "chugh the qorDu' vo' Egypt ta' taH' jaH Dung, je ta'be' ghoS, ghobe' DichDaq 'oH rain Daq chaH. vam DichDaq be the rop'a' tlhej nuq joH'a' DichDaq mup the tuqpu' vetlh yImev jaH Dung Daq pol the 'uQ'a' vo' tents.",
        19: "vam DichDaq taH the punishment vo' Egypt, je the punishment vo' Hoch the tuqpu' vetlh yImev jaH Dung Daq pol the 'uQ'a' vo' tents.",
        20: "Daq vetlh jaj pa' DichDaq taH Daq the bells vo' the horses, “le' Daq joH'a';” je the pots Daq joH'a' tuq DichDaq taH rur the bowls qaSpa' the lalDanta' Daq.",
        21: "HIja', Hoch pot Daq Jerusalem je Daq Judah DichDaq taH le' Daq joH'a' vo' Armies; je Hoch chaH 'Iv sacrifice DichDaq ghoS je tlhap vo' chaH, je cook Daq chaH. Daq vetlh jaj pa' DichDaq ghobe' longer taH a Canaanite Daq the tuq vo' joH'a' vo' Armies.",
    },
}
